		//																		   //
		//						Direct Control Interface						   //
		//																		   //
		/////////////////////////////////////////////////////////////////////////////

		/**
			@name Direct Control Interface
		*/
		//@{
		/**
			This method can be used to feed the control inputs directly. \e cyclicHorz, \e cylicVert,
			and \e pedals must between -1 and 1. \e collective must be between 0 and 1.
		*/
		virtual void	directControl( smReal cyclicHorz , smReal cylicVert , smReal pedals , smReal collective , smReal deltaTime );
		//@}


		/////////////////////////////////////////////////////////////////////////////
		//																		   //
		//						Command Interface								   //
