		/**
			@name High-level Command Interface

			Detailed information regarding the high level commands can be found in the "Bot Commands"
			section of the "RotorLib CGF" chapter in the Programmer's Guide.
		*/
		//@{


		virtual void	moveToCT( const smVec2r& position , smReal altitude , smReal speed )
		{
			setPositionContrAsMaster();
			enablePositionContrCoordinatedTurn( true );
			setPositionContrPosition( position );
			setPositionContrSpeed( speed );
			setPositionContrAltitude( altitude );
			resetPositionContrVerticalSpeed();
			enablePositionContrDontStop( false );
			resetPositionContrTerrainFollowing();
			resetPositionContrTerrainQueryInterval();
#ifdef RTDYNAMICS_EXPORT_MILITARY_FEATURES
			resetPositionContrWeaveParams();
#endif
			// Controlled turn does not use this
			//setPositionContrCHHeading( ... );

			resetVelContCTLinearAccCoeff();
			resetVelContCTVerticalAccCoeff();
			resetVelContCTMaxLinearAcc();
			resetVelContCTMaxCentrifugalAcc();
			resetVelContCTRollingSpeed();
			resetVelContCTMaxVerticalAcc();
#ifdef RTDYNAMICS_EXPORT_MILITARY_FEATURES
			resetVelContWeaveParams();
#endif
			
		}


		virtual void	moveThroughCT( const smVec2r& position , smReal altitude , smReal speed )
		{
			setPositionContrAsMaster();
			enablePositionContrCoordinatedTurn( true );
			setPositionContrPosition( position );
			setPositionContrSpeed( speed );
			setPositionContrAltitude( altitude );
			resetPositionContrVerticalSpeed();
			enablePositionContrDontStop( true );
			resetPositionContrTerrainFollowing();
			resetPositionContrTerrainQueryInterval();
#ifdef RTDYNAMICS_EXPORT_MILITARY_FEATURES
			resetPositionContrWeaveParams();
#endif
			// Controlled turn does not use this
			//setPositionContrCHHeading( ... );

			resetVelContCTLinearAccCoeff();
			resetVelContCTVerticalAccCoeff();
			resetVelContCTMaxLinearAcc();
			resetVelContCTMaxCentrifugalAcc();
			resetVelContCTMaxVerticalAcc();
			resetVelContCTRollingSpeed();
			resetVelContCHMaxForwardAcc();
			resetVelContCHMaxVerticalAcc();
			resetVelContCHMaxSidewardAcc();
#ifdef RTDYNAMICS_EXPORT_MILITARY_FEATURES
			resetVelContWeaveParams();
#endif

		}

		virtual void	moveToCH( const smVec2r& position, smReal altitude , smReal speed , smReal heading )
		{
			setPositionContrAsMaster();
			enablePositionContrCoordinatedTurn( false );
			setPositionContrPosition( position );
			setPositionContrSpeed( speed );
			setPositionContrAltitude( altitude );
			resetPositionContrVerticalSpeed();
			enablePositionContrDontStop( false );
			setPositionContrCHHeading( heading );
			resetPositionContrTerrainFollowing();
			resetPositionContrTerrainQueryInterval();
#ifdef RTDYNAMICS_EXPORT_MILITARY_FEATURES
			resetPositionContrWeaveParams();
#endif
			resetVelContCTLinearAccCoeff();
			resetVelContCTVerticalAccCoeff();
			resetVelContCTMaxLinearAcc();
			resetVelContCTMaxCentrifugalAcc();
			resetVelContCTMaxVerticalAcc();
			resetVelContCTRollingSpeed();
			resetVelContCHMaxForwardAcc();
			resetVelContCHMaxVerticalAcc();
			resetVelContCHMaxSidewardAcc();
#ifdef RTDYNAMICS_EXPORT_MILITARY_FEATURES
			resetVelContWeaveParams();
#endif

		}

		virtual void velocityHoldCT( const smVec3r& velocity , smReal turnRadius , smReal rollingSpeed	)
		{
			setVelocityControlAsMaster();

			setVelContVelocityVector( velocity );
			setVelContCTTurnRadius( turnRadius );
			enableVelContCoordinatedTurn( true );
			setVelContCTRollingSpeed( rollingSpeed );

			resetVelContCTLinearAccCoeff();
			resetVelContCTVerticalAccCoeff();
			resetVelContCTMaxLinearAcc();
			resetVelContCTMaxCentrifugalAcc();
			resetVelContCTMaxVerticalAcc();

			resetVelContCHMaxForwardAcc();
			resetVelContCHMaxVerticalAcc();
			resetVelContCHMaxSidewardAcc();

#ifdef RTDYNAMICS_EXPORT_MILITARY_FEATURES
			resetVelContWeaveParams();
#endif

		}
	
		virtual void velocityHoldCH( const smVec3r& velocity  , smReal heading )
		{
			setVelocityControlAsMaster();

			setVelContVelocityVector( velocity );
			setVelContCHHeading( heading );
			enableVelContCoordinatedTurn( false );

			resetVelContCTLinearAccCoeff();
			resetVelContCTVerticalAccCoeff();
			resetVelContCTMaxLinearAcc();
			resetVelContCTMaxCentrifugalAcc();
			resetVelContCTMaxVerticalAcc();
			resetVelContCTRollingSpeed();

			resetVelContCHMaxForwardAcc();
			resetVelContCHMaxVerticalAcc();
			resetVelContCHMaxSidewardAcc();

#ifdef RTDYNAMICS_EXPORT_MILITARY_FEATURES
			resetVelContWeaveParams();
#endif

		}


		virtual void attitudeHold( const smVec3r& hpr , smReal collective )
		{
			setAttControlAsMaster();
			setAttControlHPR( hpr );
			setAttControlCollective( collective );
		}

		virtual void land( const smVec3r& position , smReal hoverAltitude,
							smReal approachSpeed , smReal approachAngle,
							smReal touchdownSpeed,
							const smVec3r& platformVelocity = smVec3r(0.0f,0.0f,0.0f) )
		{
			setLandingAsMaster();
			setLandPosition( position );
			setLandHoverAltitude( hoverAltitude );
			setLandApproachSpeed( approachSpeed );
			setLandApproachAngle( approachAngle );
			setLandTouchdownSpeed( touchdownSpeed );
			setLandPlatformVelocity( platformVelocity );

			resetPositionContrVerticalSpeed();
			resetPositionContrTerrainFollowing();
			resetPositionContrTerrainQueryInterval();
			resetPositionContrDontStop();
#ifdef RTDYNAMICS_EXPORT_MILITARY_FEATURES
			resetPositionContrWeaveParams();
#endif

			resetVelContCTLinearAccCoeff();
			resetVelContCTVerticalAccCoeff();
			resetVelContCTMaxLinearAcc();
			resetVelContCTMaxCentrifugalAcc();
			resetVelContCTMaxVerticalAcc();
			resetVelContCTRollingSpeed();

			resetVelContCHMaxForwardAcc();
			resetVelContCHMaxVerticalAcc();
			resetVelContCHMaxSidewardAcc();
#ifdef RTDYNAMICS_EXPORT_MILITARY_FEATURES
			resetVelContWeaveParams();
#endif

		}

	
		virtual void	followRoute( const std::vector<FollowRouteController::WaypointInfo>& route , smReal waypointChangeCoefficient )
		{
			setMasterController( m_followRouteController );

			m_followRouteController->m_dynParams.m_waypoints.value().clear();
			for ( size_t i = 0 ; i < route.size() ; i++ )
			{
				FollowRouteController::WaypointInfo wi;
				wi.position = route[i].position;
				wi.altitude = route[i].altitude;
				wi.speed	= route[i].speed;
				m_followRouteController->m_dynParams.m_waypoints.value().push_back( wi );
			}

			setFollowRouteWPChangeCoefficient( waypointChangeCoefficient );

			resetPositionContrVerticalSpeed();
			resetPositionContrTerrainFollowing();
			resetPositionContrTerrainQueryInterval();
			resetPositionContrDontStop();
#ifdef RTDYNAMICS_EXPORT_MILITARY_FEATURES
			resetPositionContrWeaveParams();
#endif
			resetVelContCTLinearAccCoeff();
			resetVelContCTVerticalAccCoeff();
			resetVelContCTMaxLinearAcc();
			resetVelContCTMaxCentrifugalAcc();
			resetVelContCTMaxVerticalAcc();
			resetVelContCTRollingSpeed();

			resetVelContCHMaxForwardAcc();
			resetVelContCHMaxVerticalAcc();
			resetVelContCHMaxSidewardAcc();
#ifdef RTDYNAMICS_EXPORT_MILITARY_FEATURES
			resetVelContWeaveParams();
#endif
			
		}


		virtual void	followRoute( const std::vector<FollowRouteController::WaypointInfo>& route )
		{
			followRoute( route , 1.0f );
			resetFollowRouteWPChangeCoefficient();
		}
		
		virtual void stop(		smReal		translationalDecelerationScale	=	1.0f,
								smReal		rotationalDecelerationScale	=	1.0f,
								smReal		angleToTurn		=	0.0f,
								smReal		turningSpeedThreshold	=	-1.0f,
								bool		stopAtGivenAltitude = false,
								smReal		altitudeToStop = 20.0f )
		{
			setStopContrAsMaster();

			setStopContrAngleToTurn( angleToTurn );
			setStopContrTurningSpeedThreshold( turningSpeedThreshold );
			setStopContrTranslationalDecelerationScale( translationalDecelerationScale );
			setStopContrRotationalDecelerationScale( rotationalDecelerationScale );
			setStopContrStopAtGivenAltitude( stopAtGivenAltitude );
			setStopContrAltitudeToStop( altitudeToStop );

			resetPositionContrVerticalSpeed();
			resetPositionContrTerrainFollowing();
			resetPositionContrTerrainQueryInterval();
			resetPositionContrDontStop();
#ifdef RTDYNAMICS_EXPORT_MILITARY_FEATURES
			resetPositionContrWeaveParams();
#endif

			resetVelContCTLinearAccCoeff();
			resetVelContCTVerticalAccCoeff();
			resetVelContCTMaxLinearAcc();
			resetVelContCTMaxCentrifugalAcc();
			resetVelContCTMaxVerticalAcc();
			resetVelContCTRollingSpeed();

			resetVelContCHMaxForwardAcc();
			resetVelContCHMaxVerticalAcc();
			resetVelContCHMaxSidewardAcc();
#ifdef RTDYNAMICS_EXPORT_MILITARY_FEATURES
			resetVelContWeaveParams();
#endif
		}

		#ifdef RTDYNAMICS_EXPORT_MILITARY_FEATURES
		virtual void cmmFollowEntity( const FollowEntityController::Params& params )
		{
			setMasterController( m_flywingmanController);
			m_flywingmanController->m_dynParams = params;
		}

		#endif

